import{_ as e,o as t,c as a,Q as o}from"./chunks/framework.b67c47e6.js";const f=JSON.parse('{"title":"IFC Parsing Setup (IFC PS)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/management/ifcps/index.md","filePath":"guide/management/ifcps/index.md","lastUpdated":1789501320000}'),r={name:"guide/management/ifcps/index.md"},s=o('<h1 id="ifc-parsing-setup-ifc-ps" tabindex="-1">IFC Parsing Setup (IFC PS) <a class="header-anchor" href="#ifc-parsing-setup-ifc-ps" aria-label="Permalink to &quot;IFC Parsing Setup (IFC PS)&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">IFC Standard</p><p>The IFC standard is quite open and versatile. Each BIM application exports IFCs in its own way. Usually, it&#39;s not straightforward to detect things in IFC files. This is why we need IFC PSs.</p></div><p>The <strong>IFC PS</strong> is the information we need to <strong>understand your IFCs</strong>. A company can have several IFC PSs. You will need to select one of your IFC PSs for each project.</p><p>There are two types of entries in a IFC PS:</p><ul><li><strong>Part categories</strong>: Those are entries we need to classify parts into categories (wood profiles, plates, nail lines, ...)</li><li><strong>Part properties</strong>: Those are entries that help us find property values in parts (a zone, a milling depth, ...)</li></ul><div class="warning custom-block"><p class="custom-block-title">IFC props and values</p><p>Usually, our system tries to detect part names and values with a <strong>case insensitive</strong> criteria. So, for us, it&#39;s the same &quot;Reference&quot;, &quot;REFERENCE&quot; and &quot;reference&quot;.</p></div><h3 id="part-categories" tabindex="-1">Part categories <a class="header-anchor" href="#part-categories" aria-label="Permalink to &quot;Part categories&quot;">​</a></h3><p>For each category you have to add one or more entries that need to match somehow the information of your parts. Each entry has:</p><ul><li><strong>IFC Prop</strong>: The IFC property to look into.</li><li><strong>Type of match</strong>: Whether we need to find values that match exactly or only the prefix.</li><li><strong>Value</strong>: The value to look for in the property.</li></ul><div class="tip custom-block"><p class="custom-block-title">Example</p><p>If you add following entries to the &quot;Top Rail&quot; category:</p><table><thead><tr><th>IFC Prop</th><th>Match</th><th>Value</th></tr></thead><tbody><tr><td>REFERENCE</td><td>ALL</td><td>TOPRAIL</td></tr><tr><td>REFERENCE</td><td>PREFIX</td><td>TR</td></tr></tbody></table><p>The system will consider as Top Rails parts with &quot;REFERENCE&quot; values such as: <strong>TOPRAIL</strong>, <strong>TR</strong>12, <strong>TR</strong>, <strong>TR</strong>45.</p><p>But will never detect: TOPRAIL2, TOP_RAIL, 12TR.</p></div><h4 id="top-rail-wood" tabindex="-1">Top Rail Wood <a class="header-anchor" href="#top-rail-wood" aria-label="Permalink to &quot;Top Rail Wood&quot;">​</a></h4><p>The top rail of a panel.</p><h4 id="bottom-rail-wood" tabindex="-1">Bottom Rail Wood <a class="header-anchor" href="#bottom-rail-wood" aria-label="Permalink to &quot;Bottom Rail Wood&quot;">​</a></h4><p>The bottom rail of a panel.</p><h4 id="extra-top-wood" tabindex="-1">Extra Top Wood <a class="header-anchor" href="#extra-top-wood" aria-label="Permalink to &quot;Extra Top Wood&quot;">​</a></h4><p>Woods over the top rail, usually built after nailing the studs.</p><h4 id="extra-bottom-wood" tabindex="-1">Extra Bottom Wood <a class="header-anchor" href="#extra-bottom-wood" aria-label="Permalink to &quot;Extra Bottom Wood&quot;">​</a></h4><p>Woods below the bottom rail, usually built after nailing the studs.</p><h4 id="wood-profile" tabindex="-1">Wood profile <a class="header-anchor" href="#wood-profile" aria-label="Permalink to &quot;Wood profile&quot;">​</a></h4><p>Other wood profile parts.</p><h4 id="plate" tabindex="-1">Plate <a class="header-anchor" href="#plate" aria-label="Permalink to &quot;Plate&quot;">​</a></h4><p>Plates in a panel.</p><h4 id="frame-nail-lines" tabindex="-1">Frame Nail Lines <a class="header-anchor" href="#frame-nail-lines" aria-label="Permalink to &quot;Frame Nail Lines&quot;">​</a></h4><p>Nails in plates. Group of frame nails represented as a line. The line goes through the heads of the nails.</p><h4 id="frame-nail-singles" tabindex="-1">Frame Nail Singles <a class="header-anchor" href="#frame-nail-singles" aria-label="Permalink to &quot;Frame Nail Singles&quot;">​</a></h4><p>Nails in frame. Single nail represented as line. The line goes through the body of the nail.</p><h4 id="plate-nail-lines" tabindex="-1">Plate Nail Lines <a class="header-anchor" href="#plate-nail-lines" aria-label="Permalink to &quot;Plate Nail Lines&quot;">​</a></h4><p>Nails in plates. Group of frame nails represented as a line. The line goes through the heads of the nails.</p><h4 id="milling" tabindex="-1">Milling <a class="header-anchor" href="#milling" aria-label="Permalink to &quot;Milling&quot;">​</a></h4><p>Milling lines.</p><h4 id="plate-screw" tabindex="-1">Plate Screw <a class="header-anchor" href="#plate-screw" aria-label="Permalink to &quot;Plate Screw&quot;">​</a></h4><p>Lines representing screws in the same way as the &quot;Frame Nail Lines&quot;.</p><h4 id="sawing" tabindex="-1">Sawing <a class="header-anchor" href="#sawing" aria-label="Permalink to &quot;Sawing&quot;">​</a></h4><p>Sawing lines.</p><h4 id="hidden-material" tabindex="-1">Hidden Material <a class="header-anchor" href="#hidden-material" aria-label="Permalink to &quot;Hidden Material&quot;">​</a></h4><p>Hidden materials, that can be hidden in the 3D viewer if configured this way in the <a href="#interface-settings">interface settings</a>.</p><h4 id="glue-lines" tabindex="-1">Glue lines <a class="header-anchor" href="#glue-lines" aria-label="Permalink to &quot;Glue lines&quot;">​</a></h4><p>Glue lines for bricks.</p><h4 id="bricks-stones" tabindex="-1">Bricks / Stones <a class="header-anchor" href="#bricks-stones" aria-label="Permalink to &quot;Bricks / Stones&quot;">​</a></h4><p>Single bricks/stones.</p><h3 id="part-classes" tabindex="-1">Part classes <a class="header-anchor" href="#part-classes" aria-label="Permalink to &quot;Part classes&quot;">​</a></h3><p>Categories say what a part <em>is</em> for the machine: a stud, a rail, a plate. Part classes let you tell apart <strong>kinds</strong> of the same category when your factory treats them differently, for example I-beams and solid studs of the same height, or structural studs that need their own nailing.</p><p>The list is yours: give each class a name and add the rules that recognise it in your IFC files, with the same kind of rule as the categories (an IFC property, a type of match and a value). A part gets the <strong>first class in the list whose rules match</strong>, so put the more specific classes first. A part that matches no class simply has none, and behaves as before.</p><p>Nothing is detected automatically: a part is an I-beam only because a rule says so. Classes do not change the category or the branch of a part; they only add a label that other settings can use, starting with the framing nail matrix of the machine setups.</p><h3 id="part-properties" tabindex="-1">Part properties <a class="header-anchor" href="#part-properties" aria-label="Permalink to &quot;Part properties&quot;">​</a></h3><p>This is simpler than categories. Foe each prop we need one or more entries that tell us what is the property name to look for.</p><p>Each entry needs only an <strong>IFC Prop</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Example</p><p>If you add following entries to the &quot;Zone&quot; property:</p><table><thead><tr><th>IFC Prop</th></tr></thead><tbody><tr><td>WorkPlane</td></tr><tr><td>Layer</td></tr></tbody></table><p>The system will find the following zones for each part:</p><table><thead><tr><th>Part</th><th>&quot;WorkPlane&quot;</th><th>&quot;Layer&quot;</th><th>Detected Zone</th></tr></thead><tbody><tr><td>P1</td><td>1</td><td>2</td><td>1</td></tr><tr><td>P2</td><td>UNDEFINED</td><td>3</td><td>3</td></tr><tr><td>P3</td><td>1</td><td>UNDEFINED</td><td>1</td></tr></tbody></table><p>It picks the first that matches.</p></div><h4 id="zone-layer" tabindex="-1">Zone (layer) <a class="header-anchor" href="#zone-layer" aria-label="Permalink to &quot;Zone (layer)&quot;">​</a></h4><p>The part panel zone/layer. <code>0</code> is the frame, and the layers on each face are numbered outwards from it: <code>1</code>, <code>2</code> on one side and <code>-1</code>, <code>-2</code> on the other.</p><p>Most IFC files write that layer with a letter instead of a sign, usually <code>F</code> for the front face and <code>B</code> for the back one. produuz.it reads the letter: a value holding a <strong><code>B</code></strong> becomes a negative zone, and anything else stays positive.</p><table><thead><tr><th>IFC value</th><th>Detected zone</th></tr></thead><tbody><tr><td><code>F1</code></td><td>1</td></tr><tr><td><code>F2</code></td><td>2</td></tr><tr><td><code>B1</code></td><td>-1</td></tr><tr><td><code>B2</code></td><td>-2</td></tr><tr><td><code>Back2</code></td><td>-2</td></tr><tr><td><code>1</code></td><td>1</td></tr><tr><td><code>-1</code></td><td>-1</td></tr></tbody></table><p>Letters and other characters are stripped, so only the <code>B</code> changes the result. A value that already carries a minus sign is used as it is.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The <code>B</code> rule applies to every <strong>numeric</strong> property, not only the zone. Keep a <code>B</code> out of the values you map to <em>Nail/Screw CTC</em>, <em>Mill/Saw depth</em>, <em>Isolation order</em> and <em>Tool ID</em>, because it would turn them negative.</p></div><p>BTLx files work differently: their layer numbers already come as numbers, and the negative side is declared with the <em>Negative side zones</em> / <em>Positive side zones</em> rules instead of a letter.</p><h4 id="part-name" tabindex="-1">Part Name <a class="header-anchor" href="#part-name" aria-label="Permalink to &quot;Part Name&quot;">​</a></h4><p>The name produuz.it uses for the part. It is what the parts list, the reports and the machine file templates show.</p><p>Leave it empty and the part keeps the name the IFC element itself carries, which is what happens today. Fill it in when the useful name lives in a property set instead, for example <code>ELEMENT_NAME</code> or <code>Beschrijving</code>.</p><p>Two things worth knowing:</p><ul><li><strong>The IFC name is always kept.</strong> It stays visible in the part drawer, in the <em>Unknown parts</em> dialog of the viewer, and as its own optional column in the parts list. Nothing is lost by mapping the name somewhere else.</li><li><strong>It does not change how parts are classified.</strong> The category rules and the branch rules always match against the raw IFC properties. If you classify parts with a rule on <code>name</code> — most companies do — those rules keep reading the IFC element&#39;s own name after you fill this in. To match on the property you mapped, add a rule on that property&#39;s own key.</li></ul><h4 id="reference-we-expect-same-reference-for-same-shape" tabindex="-1">Reference (we expect same reference for same shape) <a class="header-anchor" href="#reference-we-expect-same-reference-for-same-shape" aria-label="Permalink to &quot;Reference (we expect same reference for same shape)&quot;">​</a></h4><p>This is an ID that&#39;s expected to be the same across parts with the same shape. It&#39;s usually generated as &quot;reference&quot; in Tekla Structures but can exist in other applications IFCs</p><h4 id="nail-screw-ctc" tabindex="-1">Nail/Screw CTC <a class="header-anchor" href="#nail-screw-ctc" aria-label="Permalink to &quot;Nail/Screw CTC&quot;">​</a></h4><p>The Center-to-center distance in nail and screw lines.</p><h4 id="mill-saw-depth" tabindex="-1">Mill/Saw depth <a class="header-anchor" href="#mill-saw-depth" aria-label="Permalink to &quot;Mill/Saw depth&quot;">​</a></h4><p>The milling/saw depth in a milling and sawing line.</p><h4 id="brick-type" tabindex="-1">Brick Type <a class="header-anchor" href="#brick-type" aria-label="Permalink to &quot;Brick Type&quot;">​</a></h4><p>The type of the brick.</p><h4 id="comment" tabindex="-1">Comment <a class="header-anchor" href="#comment" aria-label="Permalink to &quot;Comment&quot;">​</a></h4><p>Comment of the part.</p><h4 id="finish" tabindex="-1">Finish <a class="header-anchor" href="#finish" aria-label="Permalink to &quot;Finish&quot;">​</a></h4><p>Finish of the part.</p><h4 id="bricks-machine-brick-flag" tabindex="-1">Bricks: Machine Brick Flag <a class="header-anchor" href="#bricks-machine-brick-flag" aria-label="Permalink to &quot;Bricks: Machine Brick Flag&quot;">​</a></h4><p>Brick that is not manual but machine built.</p><h4 id="milling-v-mill-flag" tabindex="-1">Milling: V-Mill Flag <a class="header-anchor" href="#milling-v-mill-flag" aria-label="Permalink to &quot;Milling: V-Mill Flag&quot;">​</a></h4><p>Milling line that needs to be done as V-Mill.</p><h3 id="assembly-filter" tabindex="-1">Assembly filter <a class="header-anchor" href="#assembly-filter" aria-label="Permalink to &quot;Assembly filter&quot;">​</a></h3><p>A project file usually holds more than you produce: foundations, in-situ concrete, the building next door. Two lists in the <strong>Hierarchy and project</strong> tab decide what the splitter takes out of it.</p><table><thead><tr><th>List</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Split only these assemblies</strong></td><td>With rules in it, only the assemblies matching one of them are split out. Leave it empty and everything is split.</td></tr><tr><td><strong>Never split these assemblies</strong></td><td>The assemblies matching one of these are never split out.</td></tr></tbody></table><p>The rules are the same kind you use everywhere else: a property, a type of match and a value. Filter on the assembly name with the property <code>name</code>, or on a property set value such as <code>ASSEMBLY_PREFIX</code>.</p><div class="tip custom-block"><p class="custom-block-title">Two rules worth remembering</p><p><strong>Empty means everything.</strong> A parsing setup with both lists empty splits every assembly, exactly as before.</p><p><strong>The drop list wins.</strong> If an assembly matches both lists, it is not split. That is how you keep a whole prefix and still leave a few names out of it.</p></div><p>An assembly that is not split leaves nothing behind: no IFC file, no design, and nothing in the phase and batch counts.</p><details class="details custom-block"><summary>Example</summary><p><em>Split only these assemblies:</em> <code>ASSEMBLY_PREFIX</code> starts with <code>WA</code></p><p><em>Never split these assemblies:</em> <code>name</code> contains <code>_TEST</code></p><p>You get every wall, except the ones whose name carries <code>_TEST</code>. Roofs, floors and everything else in the file are left alone.</p></details><h3 id="reading-a-property-from-a-specific-property-set" tabindex="-1">Reading a property from a specific property set <a class="header-anchor" href="#reading-a-property-from-a-specific-property-set" aria-label="Permalink to &quot;Reading a property from a specific property set&quot;">​</a></h3><p>Normally produuz.it looks for a property <strong>anywhere in the element</strong>: in any of its property sets, and among the element&#39;s own attributes. That is what you want almost always.</p><p>It is a problem when the same property name exists in two property sets with different values — one exporter&#39;s <code>REFERENCE</code> and your own <code>REFERENCE</code>, say. Then it is luck which one is read.</p><p>Every rule and every property name has a <strong>Read from a specific property set</strong> checkbox for exactly that:</p><table><thead><tr><th>Checkbox</th><th>Field</th><th>What is read</th></tr></thead><tbody><tr><td>unticked</td><td>—</td><td>The property wherever it appears. The normal case.</td></tr><tr><td>ticked</td><td><code>Tekla_Common</code></td><td>Only that property set. Another set carrying a property of the same name is ignored.</td></tr><tr><td>ticked</td><td><em>(left empty)</em></td><td>Only the element&#39;s own attributes: <code>name</code>, <code>ifc_tag</code>, <code>ifc_id</code>, <code>object_type</code>, <code>description</code>.</td></tr></tbody></table><p>Tick it only when you have a reason to. An unticked entry behaves exactly as it always has, and existing setups are untouched.</p><div class="warning custom-block"><p class="custom-block-title">BTLx</p><p>BTLx files have no property sets — their parts carry plain attributes — so the checkbox is not offered on the BTLx rules, and a rule that names a property set never matches a BTLx part.</p></div>',90),i=[s];function n(l,d,h,p,c,m){return t(),a("div",null,i)}const g=e(r,[["render",n]]);export{f as __pageData,g as default};
